SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'E'), 'bodenart_tab5', 'Bodenart nach Tabelle 5 (Zeile)', 'enum', NULL, false, '§6.7, Tab. 5', 'Plan 3: Treiber der Tab.-5-Zeile (mit der Versuchsanordnung KD/ZY/TX) → erreichbare Versuchsklasse, Eignung, SB und U0 gefüllt; die Bodenart nach DIN 4022-1 (DIN-18130-1-01) bleibt Freitext. Ton/Schluff mit KD oder TX und Sand-Ton-Gemisch mit TX haben bis zur PDF-Prüfung keine Zeile (din18130_1-U-1).', 'imported_unverified', '\caption{Tabelle 5: Geeignete Versuchsanordnungen in Abhängigkeit von den Bodenarten} — Es bestehen verschiedene Möglichkeiten der Versuchsanordnung (siehe Tabelle 5). Die Versuchsanordnung ist entsprechend den jeweiligen Erfordernissen des Anwendungsfalls zusammenzustellen. Bei Auswahl der Versuchsanordnung ist zu beachten, ob der Durchlässigkeitsbeiwert bei voller Wassersättigung und stationärer Strömung benötigt wird, ob eine Bestimmung bei nicht voller Wassersättigung mit stationärer Strömung ausreicht oder ob nur eine überschlägliche Ermittlung ohne Kontrolle der stationären Strömung genügt.', 'select_one', NULL, NULL, NULL, '[{"value":"ton_schluff","label_de":"Ton, Schluff","order_index":0},{"value":"feinsand","label_de":"Feinsand","order_index":1},{"value":"mittel_grobsand","label_de":"Mittel- und Grobsand","order_index":2},{"value":"sand_kies","label_de":"Sand-KiesGemisch","order_index":3},{"value":"sand_ton","label_de":"Sand-TonGemisch","order_index":4},{"value":"kies_sand_ton","label_de":"Kies-Sand-Ton-Gemisch","order_index":5}]'::jsonb, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
