SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'D'), 'stroemung_stationaer', 'Strömung stationär nachgewiesen (Tab. 4)', 'boolean', NULL, false, '§3.8, §6.3, Tab. 4', 'Plan 3: zweite Achse der Tab. 4 (mit „Sättigungsdruck aufgebracht“ → versuchsklasse_tab4). Nein bei nachgewiesener Sättigung = Klasse 1b: „*) Die stationäre Strömung wird nicht nachgewiesen. Aufgrund der Versuchsbedingungen, insbesondere aufgrund der vorausgegangenen Phase der Wassersättigung kann aber angenommen werden, daß die Strömung stationär ist.“ Nachweis nach §6.3 (ein- = ausströmende Wassermenge); Umstellung von CR-04 STAGED (din18130_1-G-2).', 'imported_unverified', '\hline Versuchsklasse & Wassersättigung nachgewiesen und kontrolliert nach DIN 18137-2 & Strömung stationär nachgewiesen \\ — \hline \multicolumn{3}{|c|}{*) Die stationäre Strömung wird nicht nachgewiesen. Aufgrund der Versuchsbedingungen, insbesondere aufgrund der vorausgegangenen Phase der Wassersättigung kann aber angenommen werden, daß die Strömung stationär ist.} \\', 'attestation', NULL, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
