SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'D'), 's_r_band', 'Sättigungszahl-Zeile der Tabelle 3 (≥ 0,95 / 0,90 / 0,85)', 'enum', NULL, false, '§6.5, Tab. 3', 'Plan 3: SR-2-Auswahl der Tab.-3-Zeile (Zwischenwerte sind in Tab. 3 nicht definiert; Beispiel 9.3 interpoliert linear: S_ra = 0,88 → u_o = 720 kN/m²) — füllt u_0; die Sättigungszahl S_r (DIN-18130-1-01) leitet die Wahl, ein Abgleich ist STAGED (din18130_1-G-11).', 'imported_unverified', 'Feinkörnige und gemischtkörnige Böden sowie Sande werden durch Aufbringen eines Sättigungsdrucks gesättigt. Dazu wird das Porenwasser in dem Probekörper mit einem hydrostatischen Druck (Sättigungsdruck, back pressure) belastet (siehe Tabelle 3). Dies ist nur mit den Versuchsanordnungen nach Bild 8 und Bild 9 möglich. — \caption{Tabelle 3: Sättigungsdruck $u_{0}$ in Abhängigkeit von der Sättigungszahl $S_{\mathrm{r}}$}', 'select_one', NULL, NULL, 'saettigung_aufgebracht == true', '[{"value":"ge095","label_de":"S_r ≥ 0,95","order_index":0},{"value":"e090","label_de":"S_r = 0,90","order_index":1},{"value":"e085","label_de":"S_r = 0,85","order_index":2}]'::jsonb, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 's_r_band') AND w.code = 'DIN-18130-1-02' AND s.code = 'DIN-18130-1';
UPDATE fields f SET widget = 'lookup_fill', ui_config = '{"source_label":"Tab. 3"}'::jsonb, lookup = '{"table_code":"TAB3","role":"value","keys":[{"column":"s_r_band","from_symbol":"s_r_band"}],"value":"u_0_kn_m2"}'::jsonb, visible_when = NULL FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND f.symbol = 'u_0' AND w.code = 'DIN-18130-1-02' AND s.code = 'DIN-18130-1' AND f.active;
