SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'E'), 'probe_durchmesser_mm', 'Probendurchmesser (KD: mindestens 70 mm)', 'number', 'mm', false, '§7.1.1', 'Plan 3: Eingabe für das Kompressions-Durchlässigkeitsgerät; die Prüfung d ≥ 70 mm und l_0 ≥ 20 mm (Höhe = l_0 auf DIN-18130-1-03) ist STAGED (din18130_1-G-7).', 'imported_unverified', 'Der Versuch eignet sich für feinkörnige Böden, insbesondere für Tone und Schluffe. Die Probe sollte einen Durchmesser von mindestens 70 mm und eine Höhe von mindestens 20 mm haben.', 'scalar', NULL, NULL, 'versuchsanordnung == ''KD''', NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'probe_durchmesser_mm') AND w.code = 'DIN-18130-1-02' AND s.code = 'DIN-18130-1';
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'C'), 'ablesungen', 'Ablesungen (je Messintervall: t, h_o/h_u/p_o/p_u/V_w bzw. h_1/h_2, T)', 'json', NULL, false, '§7.1.4.4, §8.1, §8.2, Tab. 7, Tab. 8, Tab. 11', 'Plan 3: Zeilen je Ablesung mit k je Zeile (Gl. 8 mit Q = V_w/t bei konstantem, Gl. 9 bei veränderlichem Gefälle — Umschaltung über gefaelle_typ), h nach Tab. 11, α je Zeile (Gl. 6), k_10 je Zeile; Mittelwerte → k_T_mean (DIN-18130-1-03-D1), k_10_calc (-D3), i-Bereich → i_max_calc / i_min_calc (-D4 / -D5). Ablösung der Einzelskalare und Umstellung von Gl. 6/8/9 STAGED (din18130_1-R-1 / R-2 / D-3).', 'imported_unverified', 'Bei jeder Ablesung wird in der Regel auch die Temperatur gemessen. Der Durchlässigkeitsversuch darf beendet werden, wenn sich aus den Messungen ein annähernd gleichbleibender $k$-Wert ergibt. — k=\frac{Q \cdot l}{A \cdot h} \tag{8} — 1) Versuchsanordnung nach Bild 6: h die Differenz der Standrohrspiegelhöhen; $l$ der Abstand der Ansatzpunkte der beiden Standrohre. 2) Anordnung nach Bild 8 und Bild 9: $h=\left(p / \gamma_{\mathrm{w}}-\Delta h\right)$, wobei $p$ Wasserdruck im Druckzylinder, (siehe Bild 8); $l$ die Höhe des Probekörpers $l_{0}$; $h=\left(p_{2}-p_{1}\right) / \gamma_{\mathrm{w}}$, (siehe Bild 9). 3) Anordnung nach Bild 3A: $h=h_{\mathrm{o}}\left(\gamma_{\mathrm{w}}-\gamma_{\text {org }}\right) / \gamma_{\mathrm{w}}$, (siehe Gleichung (7)); $l$ die Höhe des Probekörpers $l_{0}$. — k=\frac{a \cdot l_{0}}{A \cdot t} \ln \frac{h_{1}}{h_{2}} \tag{9} — & h=h_{\mathrm{o}}-h_{\mathrm{u}}+\left(p_{\mathrm{o}}-p_{\mathrm{u}}\right) / \gamma_{\mathrm{w}}', 'register', '{"title":"Ablesungen","subtitle":"§8.1 / §8.2 — je Messintervall eine Zeile; Versuchsende bei annähernd gleichbleibendem k (§7.1.4.4)","add_label":"+ Ablesung","placement":"section","columns":[{"key":"nr","label":"Nr.","type":"number","required":true,"min":1},{"key":"t_s","label":"t","type":"number","unit":"s","required":true,"min":0,"aria_label":"Meßzeitspanne t"},{"key":"h_o","label":"h_o","type":"number","unit":"m","required":true,"visible_when":"gefaelle_typ == ''konstant''","aria_label":"Standrohrspiegelhöhe Oberstrom h_o"},{"key":"h_u","label":"h_u","type":"number","unit":"m","required":true,"visible_when":"gefaelle_typ == ''konstant''","aria_label":"Standrohrspiegelhöhe Unterstrom h_u"},{"key":"p_o","label":"p_o","type":"number","unit":"kN/m²","required":true,"visible_when":"gefaelle_typ == ''konstant''","placeholder":"0 wenn drucklos","aria_label":"Oberwasserdruck p_o"},{"key":"p_u","label":"p_u","type":"number","unit":"kN/m²","required":true,"visible_when":"gefaelle_typ == ''konstant''","placeholder":"0 wenn drucklos","aria_label":"Unterwasserdruck p_u"},{"key":"v_w","label":"V_w","type":"number","unit":"m³","required":true,"min":0,"visible_when":"gefaelle_typ == ''konstant''","aria_label":"Wasservolumen V_w"},{"key":"h_1","label":"h_1","type":"number","unit":"m","required":true,"min":0,"visible_when":"gefaelle_typ == ''veraenderlich''","aria_label":"Wasserhöhe im Standrohr bei Versuchsbeginn h_1"},{"key":"h_2","label":"h_2","type":"number","unit":"m","required":true,"min":0,"visible_when":"gefaelle_typ == ''veraenderlich''","aria_label":"Wasserhöhe im Standrohr bei Versuchsende h_2"},{"key":"t_c","label":"T","type":"number","unit":"°C","required":true,"aria_label":"Wassertemperatur T"},{"key":"h_row","label":"h","type":"derived","expr":"h_o - h_u + (p_o - p_u) / gamma_w"},{"key":"i_row","label":"i","type":"derived","expr":"if(gefaelle_typ == ''konstant'', h_row / l, h_1 / l_0)"},{"key":"k_row","label":"k (Ablesung)","type":"derived","expr":"if(gefaelle_typ == ''konstant'', v_w * l / (A * h_row * t_s), a * l_0 / (A * t_s) * ln(h_1 / h_2))"},{"key":"k_exp","label":"k: Exponent (Basis 10)","type":"derived","expr":"floor(log10(k_row))"},{"key":"k_mant","label":"k: Mantisse","type":"derived","expr":"k_row / 10^floor(log10(k_row))"},{"key":"alpha_row","label":"α","type":"derived","expr":"1.359 / (1 + 0.0337 * t_c + 0.00022 * t_c^2)"},{"key":"k10_row","label":"k_10 (Ablesung)","type":"derived","expr":"k_row * alpha_row"},{"key":"k10_exp","label":"k_10: Exponent (Basis 10)","type":"derived","expr":"floor(log10(k10_row))"},{"key":"k10_mant","label":"k_10: Mantisse","type":"derived","expr":"k10_row / 10^floor(log10(k10_row))"}],"footer":["k_T_mean","k_10_calc","i_max_calc","i_min_calc"],"note":"Bei jeder Ablesung wird in der Regel auch die Temperatur gemessen. Der Durchlässigkeitsversuch darf beendet werden, wenn sich aus den Messungen ein annähernd gleichbleibender $k$-Wert ergibt. γ_w, l, l_0, A und a sind die Felder dieses Arbeitsblatts (Zeilenwerte lesen sie mit); drucklose Anordnungen (Bild 6): p_o = p_u = 0 eintragen. Alle vollständigen Zeilen gehen in die Mittelwerte ein (din18130_1-J-1)."}'::jsonb, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'ablesungen') AND w.code = 'DIN-18130-1-03' AND s.code = 'DIN-18130-1';
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'C'), 'k_T_mean', 'k_T (Mittel der Ablesungen, bei Versuchstemperatur)', 'number', 'm/s', false, '§7.1.4.4, §8.1, §8.2', 'Plan 3: Ausgabe der Gleichung DIN-18130-1-03-D1 (mean_rows über ablesungen.k_row); Umstellung von Gl. 6 auf diesen Wert STAGED (din18130_1-R-2).', 'imported_unverified', 'Bei jeder Ablesung wird in der Regel auch die Temperatur gemessen. Der Durchlässigkeitsversuch darf beendet werden, wenn sich aus den Messungen ein annähernd gleichbleibender $k$-Wert ergibt. — & \qquad k_{\mathrm{T}}=\frac{V_{\mathrm{w}} \cdot l}{A \cdot h \cdot t} \\', 'derived', NULL, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'k_T_mean') AND w.code = 'DIN-18130-1-03' AND s.code = 'DIN-18130-1';
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'K'), 'alpha_calc', 'Korrekturbeiwert α nach Gl. 6 (aus T dieses Arbeitsblatts)', 'number', NULL, false, '§5.7, Gl. 6, Tab. 2', 'Plan 3: Ausgabe der Gleichung DIN-18130-1-03-D2 — 1,359 / (1 + 0,0337·T + 0,00022·T²); Tab. 2 druckt 1,158 / 1,000 / 0,874 / 0,771 / 0,686 für 5 / 10 / 15 / 20 / 25 °C; Ablösung des Eingabefelds alpha (DIN-18130-1-01) STAGED (din18130_1-D-1).', 'imported_unverified', 'k_{10}=\frac{1,359}{1+0,0337 \cdot T+0,00022 \cdot T^{2}} k_{\mathrm{T}}=\alpha \cdot k_{\mathrm{T}} \tag{6} — $T$ die Wassertemperatur beim Versuch, in ${ }^{\circ} \mathrm{C}$;', 'derived', NULL, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'alpha_calc') AND w.code = 'DIN-18130-1-03' AND s.code = 'DIN-18130-1';
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'C'), 'k_10_calc', 'k_10 (auf 10 °C umgerechnet, aus den Ablesungen)', 'number', 'm/s', false, '§5.7, Gl. 6, §8.4', 'Plan 3: Ausgabe der Gleichung DIN-18130-1-03-D3 (k_T_mean · alpha_calc, wie Tab. 11: k_10 = 3,48·10⁻¹⁰ als Mittel der drei Ablesungen); Übergabe an DIN-18130-1-04 k_10 / -05 k_f STAGED (din18130_1-R-2 / R-3).', 'imported_unverified', 'k_{10}=\frac{1,359}{1+0,0337 \cdot T+0,00022 \cdot T^{2}} k_{\mathrm{T}}=\alpha \cdot k_{\mathrm{T}} \tag{6} — & \alpha \text { für } T=0,5 \times(19,0+22,0) \\ — \hline \multicolumn{6}{|l|}{Durchlässigkeitsbeiwert $k_{10}=3,48 \times 10^{-10} \mathrm{~m} / \mathrm{s}$} \\', 'derived', NULL, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'k_10_calc') AND w.code = 'DIN-18130-1-03' AND s.code = 'DIN-18130-1';
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'C'), 'i_max_calc', 'Größtes hydraulisches Gefälle max. i (über die Ablesungen)', 'number', NULL, false, '§8.4, Gl. 3', 'Plan 3: Ausgabe der Gleichung DIN-18130-1-03-D4 (max_rows über ablesungen.i_row: konstant h/l, veränderlich h_1/l_0); Beispiel 9.1: max. i = 33.', 'imported_unverified', 'Als Versuchsergebnis sind der Durchlässigkeitsbeiwert $k$, umgerechnet auf die Temperatur von $10^{\circ} \mathrm{C}$ und das hydraulische Gefälle $i$ anzugeben. Bei Versuchen mit veränderlichem hydraulischen Gefälle ist dessen Bereich (größtes und kleinstes hydraulisches Gefälle) anzugeben. Ferner sind mit dem Versuchsergebnis mitzuteilen: — Grenzfälle: $\quad \max . i=33$; min. $i=25$ bzw. 27', 'derived', NULL, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'i_max_calc') AND w.code = 'DIN-18130-1-03' AND s.code = 'DIN-18130-1';
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'C'), 'i_min_calc', 'Kleinstes hydraulisches Gefälle min. i (über die Ablesungen)', 'number', NULL, false, '§8.4, Gl. 3', 'Plan 3: Ausgabe der Gleichung DIN-18130-1-03-D5 (min_rows: konstant h/l, veränderlich h_2/l_0 am Ende der Ablesung); Beispiel 9.1: min. i = 25 bzw. 27; der Bereich ist auf DIN-18130-1-05 (i_bereich) als Text anzugeben.', 'imported_unverified', 'Als Versuchsergebnis sind der Durchlässigkeitsbeiwert $k$, umgerechnet auf die Temperatur von $10^{\circ} \mathrm{C}$ und das hydraulische Gefälle $i$ anzugeben. Bei Versuchen mit veränderlichem hydraulischen Gefälle ist dessen Bereich (größtes und kleinstes hydraulisches Gefälle) anzugeben. Ferner sind mit dem Versuchsergebnis mitzuteilen: — Grenzfälle: $\quad \max . i=33$; min. $i=25$ bzw. 27', 'derived', NULL, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'i_min_calc') AND w.code = 'DIN-18130-1-03' AND s.code = 'DIN-18130-1';
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'I'), 'versuche', 'Durchströmungsversuche (mindestens drei bei Prüfung des Dichteeinflusses, §5.3)', 'json', NULL, false, '§5.3, §8.3, Tab. 6, Tab. 10', 'Plan 3: Zeilen je Versuch (Porenzahl e, n = e/(1+e), ϱ_d, S_ra/S_re, k_10); Mittel → k_10_runs_mean (DIN-18130-1-04-D1, Beispiel 9.3: 3,77·10⁻⁹), Anzahl → versuche_count (-D2); das Gate „mindestens drei“ ist STAGED (din18130_1-G-5).', 'imported_unverified', 'Ist der Einfluß der Dichte auf die Durchlässigkeit zu prüfen, dann sind mindestens drei Durchströmungsversuche mit jeweils unterschiedlichen Porenzahlen des Probekörpers auszuführen (siehe 8.3). — \hline \multicolumn{5}{|l|}{Durchlässigkeitsbeiwert $k_{10}=3,77 \times 10^{-9} \mathrm{~m} / \mathrm{s}$} \\', 'register', '{"title":"Durchströmungsversuche (Versuche je Spannungszustand / Porenzahl)","subtitle":"§5.3 / §8.3 — je Versuch Porenzahl, Trockendichte, Sättigungszahlen und das Ergebnis k_10","add_label":"+ Versuch","placement":"section","columns":[{"key":"nr","label":"Versuch","type":"number","required":true,"min":1},{"key":"sigma_kn_m2","label":"statische Belastung","type":"number","unit":"kN/m²","min":0},{"key":"e","label":"e","type":"number","min":0,"aria_label":"Porenzahl e"},{"key":"n_pore_row","label":"n = e/(1+e)","type":"derived","expr":"e / (1 + e)"},{"key":"rho_d","label":"ϱ_d","type":"number","unit":"g/cm³","min":0,"aria_label":"Trockendichte ϱ_d"},{"key":"s_ra","label":"S_ra","type":"number","min":0,"max":1,"aria_label":"Sättigungszahl vor dem Versuch S_ra"},{"key":"s_re","label":"S_re","type":"number","min":0,"max":1,"aria_label":"Sättigungszahl nach dem Versuch S_re"},{"key":"k_10_run","label":"k_10","type":"number","unit":"m/s","required":true,"min":0,"aria_label":"k_10 des Versuchs"}],"footer":["k_10_runs_mean","versuche_count"],"note":"Ist der Einfluß der Dichte auf die Durchlässigkeit zu prüfen, dann sind mindestens drei Durchströmungsversuche mit jeweils unterschiedlichen Porenzahlen des Probekörpers auszuführen (siehe 8.3). k_10 je Versuch wird aus den Ablesungen des jeweiligen Versuchs eingetragen (verschachtelte Register sind nicht gebaut — din18130_1-F-1)."}'::jsonb, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'versuche') AND w.code = 'DIN-18130-1-04' AND s.code = 'DIN-18130-1';
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'I'), 'k_10_runs_mean', 'k_10 (Mittel über die Versuche)', 'number', 'm/s', false, '§8.3, §9.3, Tab. 10', 'Plan 3: Ausgabe der Gleichung DIN-18130-1-04-D1 (mean_rows über versuche.k_10_run; Tab. 10: (3,84 + 3,74 + 3,74)/3 = 3,77·10⁻⁹ m/s).', 'imported_unverified', '\hline \multicolumn{5}{|l|}{Durchlässigkeitsbeiwert $k_{10}=3,77 \times 10^{-9} \mathrm{~m} / \mathrm{s}$} \\', 'derived', NULL, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
