INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'I'), 'versuche_count', 'Anzahl der Durchströmungsversuche', 'number', NULL, false, '§5.3', 'Plan 3: Ausgabe der Gleichung DIN-18130-1-04-D2 (count_rows über versuche); §5.3 verlangt mindestens drei, wenn der Einfluß der Dichte zu prüfen ist (Gate STAGED, din18130_1-G-5).', 'imported_unverified', 'Ist der Einfluß der Dichte auf die Durchlässigkeit zu prüfen, dann sind mindestens drei Durchströmungsversuche mit jeweils unterschiedlichen Porenzahlen des Probekörpers auszuführen (siehe 8.3).', 'derived', NULL, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
