INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'I'), 'bereich_code', 'Durchlässigkeitsbereich nach Tabelle 1 als Code (1 = sehr schwach durchlässig, unter 10⁻⁸ · 2 = schwach durchlässig, 10⁻⁸ bis 10⁻⁶ · 3 = durchlässig, über 10⁻⁶ bis 10⁻⁴ · 4 = stark durchlässig, über 10⁻⁴ bis 10⁻² · 5 = sehr stark durchlässig, über 10⁻²)', 'number', NULL, false, '§3.7, Tab. 1', 'Plan 3: Ausgabe der Gleichung DIN-18130-1-04-D3 aus k_10 (Gl. 6); die Handauswahl durchlaessigkeitsbereich (DIN-18130-1-01) zu ersetzen ist STAGED (din18130_1-D-2).', 'imported_unverified', '\hline \multicolumn{6}{|l|}{Durchlässigkeitsbeiwert $k_{10}=3,48 \times 10^{-10} \mathrm{~m} / \mathrm{s}$} \\', 'derived', NULL, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'bereich_code') AND w.code = 'DIN-18130-1-04' AND s.code = 'DIN-18130-1';
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'K'), 'pflichtangaben', 'Pflichtangaben des Versuchsberichts (§8.4, 5 + 9 Punkte)', 'json', NULL, false, '§8.4', 'Plan 3: Mehrfachauswahl über die 14 gedruckten Berichtsangaben; Vollständigkeit (alle 14) als Gate neben dem Boolean versuchsbericht_vollstaendig (CR-06) ist STAGED (din18130_1-G-4).', 'imported_unverified', 'Ferner sind mit dem Versuchsergebnis mitzuteilen: 1) Angaben zum Versuch - Bezeichnung nach Abschnitt 4 - Versuchsdauer $t$ - Sättigungsdruck $u_{0}$ - Raumtemperatur $T$ - Durchströmungsrichtung 2) Angaben zur Probe - Bodenart nach DIN 4022-1 - Bodengruppe nach DIN 18196 - Größtkorn max. d', 'select_many', '{"title":"Pflichtangaben §8.4","subtitle":"Mit dem Versuchsergebnis mitzuteilen — 1) Angaben zum Versuch · 2) Angaben zur Probe","note":"Als Versuchsergebnis sind der Durchlässigkeitsbeiwert $k$, umgerechnet auf die Temperatur von $10^{\\circ} \\mathrm{C}$ und das hydraulische Gefälle $i$ anzugeben. Bei Versuchen mit veränderlichem hydraulischen Gefälle ist dessen Bereich (größtes und kleinstes hydraulisches Gefälle) anzugeben. Ferner sind mit dem Versuchsergebnis mitzuteilen:","groups":[{"label":"1) Angaben zum Versuch","options":["bezeichnung","versuchsdauer","saettigungsdruck","raumtemperatur","durchstroemungsrichtung"]},{"label":"2) Angaben zur Probe","options":["bodenart","bodengruppe","groesstkorn","trockendichte","porenzahl","wassergehalt","saettigungszahl","probenart","masse"]}]}'::jsonb, NULL, NULL, '[{"value":"bezeichnung","label_de":"Bezeichnung nach Abschnitt 4","order_index":0},{"value":"versuchsdauer","label_de":"Versuchsdauer t","order_index":1},{"value":"saettigungsdruck","label_de":"Sättigungsdruck u_0","order_index":2},{"value":"raumtemperatur","label_de":"Raumtemperatur T","order_index":3},{"value":"durchstroemungsrichtung","label_de":"Durchströmungsrichtung","order_index":4},{"value":"bodenart","label_de":"Bodenart nach DIN 4022-1","order_index":5},{"value":"bodengruppe","label_de":"Bodengruppe nach DIN 18196","order_index":6},{"value":"groesstkorn","label_de":"Größtkorn max. d","order_index":7},{"value":"trockendichte","label_de":"Trockendichte ϱ_d","order_index":8},{"value":"porenzahl","label_de":"Porenzahl bzw. Porenanteil e bzw. n","order_index":9},{"value":"wassergehalt","label_de":"Wassergehalt vor und nach dem Versuch w_a und w_e","order_index":10},{"value":"saettigungszahl","label_de":"Sättigungszahl vor und nach dem Versuch (falls kein Sättigungsdruck aufgebracht) S_ra und S_re","order_index":11},{"value":"probenart","label_de":"Art der Probe (Sonderprobe, aufbereitet usw.)","order_index":12},{"value":"masse","label_de":"Maße des Probekörpers","order_index":13}]'::jsonb, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'pflichtangaben') AND w.code = 'DIN-18130-1-05' AND s.code = 'DIN-18130-1';
UPDATE fields f SET widget = 'scalar', ui_config = NULL, lookup = NULL, visible_when = 'gefaelle_typ == ''veraenderlich''' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND f.symbol = 'i_bereich' AND w.code = 'DIN-18130-1-05' AND s.code = 'DIN-18130-1' AND f.active;
COMMIT;
